/* ================================================
 * IG 风格连续气泡 + 我方 #0E44E2 / 对方 #F0F4F7
 * 顶栏：返回/视频/设置按钮替换为图片，电话隐藏
 * ================================================ */

/* ----- 全局布局（IG 风格）----- */
:root {
  --chat-messages-padding: 8px 12px;
  --chat-message-max-width: 78%;
  --plain-gap-between-groups: 12px;
  --plain-gap-within-group: 2px;
  --plain-content-max-width: 78%;
  --plain-padding-left-them: 0px;
  --plain-avatar-size: 32px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;
}

/* ========== 顶栏样式 ========== */
.chat-header-custom {
  background: #ffffff !important;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1) !important;
  box-shadow: none !important;
}

/* ----- 返回按钮 ----- */
.header-btn-back {
  background: transparent !important;
  border: none !important;
  width: 19px !important;
  height: 19px !important;
}
.header-btn-back svg,
.header-btn-back::before {
  display: none !important;
}
.header-btn-back {
  background-image: url('https://img.heliar.top/file/1776080964914_retouch_2026041319490572.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ----- 电话按钮（隐藏但可点击）----- */
.header-btn-phone {
  opacity: 0 !important;
  display: inline-flex !important;
  pointer-events: auto !important;
  min-width: 32px !important;
  min-height: 32px !important;
}
.header-btn-phone svg {
  display: none !important;
}
.header-btn-phone::before,
.header-btn-phone::after {
  display: none !important;
}

/* ----- 视频按钮 ----- */
.header-btn-video {
  background: transparent !important;
  border: none !important;
  width: 22px !important;
  height: 22px !important;
}
.header-btn-video svg,
.header-btn-video::before {
  display: none !important;
}
.header-btn-video {
  background-image: url('https://img.heliar.top/file/1776080968655_retouch_2026041319473543.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ----- 设置按钮 ----- */
.header-btn-info {
  background: transparent !important;
  border: none !important;
  width: 25px !important;
  height: 25px !important;
}
.header-btn-info svg,
.header-btn-info::before,
.header-btn-info::after {
  display: none !important;
}
.header-btn-info {
  background-image: url('https://img.heliar.top/file/1776080964059_retouch_2026041319481592.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ----- 顶栏标题 ----- */
.chat-header-title {
  color: #1a2a3a !important;
  font-size: 16px !important;
  font-weight: 600 !important;
}
.chat-header-subtitle {
  color: #8e8e8e !important;
  font-size: 12px !important;
}
.header-avatar-container {
  width: 36px !important;
  height: 36px !important;
  border-radius: 50% !important;
}
.header-avatar-container img {
  border-radius: 50% !important;
  object-fit: cover !important;
}

/* ========== 气泡样式 ========== */

/* 我方头像隐藏 */
.msg-avatar-me-container {
  display: none !important;
}

/* 对方头像：连续消息只在最后一条显示 */
.msg-avatar-them-container {
  visibility: hidden !important;
  width: 32px !important;
  margin-right: 8px !important;
}
.msg-avatar-them-container.is-last,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}
.msg-avatar-them-inner {
  width: 32px !important;
  height: 32px !important;
  border-radius: 50% !important;
  object-fit: cover !important;
}

/* 对方气泡 #F0F4F7 */
.bubble-them-custom {
  background: #F0F4F7 !important;
  background-color: #F0F4F7 !important;
  background-image: none !important;
  color: #1a2a3a !important;
  font-size: 15px !important;
  line-height: 1.4 !important;
  padding: 10px 14px !important;
  box-shadow: none !important;
}
.msg-them .bubble-them-custom {
  border-radius: 20px !important;
}
.msg-them.is-first .bubble-them-custom {
  border-bottom-left-radius: 6px !important;
}
.msg-them.is-mid .bubble-them-custom {
  border-radius: 6px 20px 20px 6px !important;
}
.msg-them.is-last .bubble-them-custom {
  border-top-left-radius: 6px !important;
}
.msg-them.is-single .bubble-them-custom {
  border-radius: 20px !important;
}

/* 我方气泡 #0E44E2 */
.bubble-me-custom {
  background: #0E44E2 !important;
  background-color: #0E44E2 !important;
  color: #ffffff !important;
  font-size: 15px !important;
  line-height: 1.4 !important;
  padding: 10px 14px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08) !important;
}
.msg-me .bubble-me-custom {
  border-radius: 20px !important;
}
.msg-me.is-first .bubble-me-custom {
  border-bottom-right-radius: 6px !important;
}
.msg-me.is-mid .bubble-me-custom {
  border-radius: 20px 6px 6px 20px !important;
}
.msg-me.is-last .bubble-me-custom {
  border-top-right-radius: 6px !important;
}
.msg-me.is-single .bubble-me-custom {
  border-radius: 20px !important;
}

/* 时间戳居中纯文字 */
.timestamp-custom,
.date-divider-custom {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  text-align: center !important;
  font-size: 11px !important;
  color: #8e8e8e !important;
  background: transparent !important;
  padding: 0 !important;
  border-radius: 0 !important;
  width: 100% !important;
  margin: 16px 0 !important;
  font-weight: 400 !important;
  box-shadow: none !important;
  border: none !important;
}
.chat-messages-area .timestamp-custom,
.chat-messages-area .date-divider-custom {
  width: 100% !important;
  display: flex !important;
  justify-content: center !important;
}

/* 消息状态文字 */
.msg-status-custom {
  font-size: 10px !important;
  color: #8e8e8e !important;
  margin-top: 2px !important;
  margin-right: 4px !important;
}

/* 消息行布局 */
.msg-bubble-wrapper.msg-them {
  display: flex !important;
  flex-direction: row !important;
  align-items: flex-end !important;
}

/* ===== 底栏 - 实色白色背景，无分割线 ===== */

.input-area-custom {
   position: absolute !important;
   bottom: 0 !important;
   left: 0 !important;
   right: 0 !important;
   z-index: 60 !important;
   background: #ffffff !important;
   backdrop-filter: none !important;
   -webkit-backdrop-filter: none !important;
   border-top: none !important;
   padding: 8px 12px 8px 12px !important;
   padding-bottom: max(8px, var(--nuo-safe-bottom)) !important;
   overflow: visible !important;
   transform: none !important;

   /* 伪元素*/
   &::after {
     content: "" !important;
     position: absolute !important;
     left: 43px !important;
     bottom: 16px !important;
     width: 68px !important;     
     height: 68px !important;    
     background-image: url("https://i.postimg.cc/hvHc9bTt/IMG_2439.png") !important;
     background-size: contain !important;
     background-repeat: no-repeat !important;
     background-position: center !important;
     pointer-events: none !important;
     z-index: 5 !important;
   }
}

/* 移除所有原有伪元素 */
.input-area-custom::before {
   display: none !important;
   content: none !important;
}

/* 输入行包装 */
.input-row-wrapper {
   display: flex !important;
   flex-direction: row !important;
   align-items: flex-end !important;
   gap: 10px !important;
   position: relative !important;
   z-index: 10 !important;
   margin-bottom: 0 !important;
   padding-left: 50px !important;
}

/* ===== 加号按钮 - 调整为 26px ===== */
.input-btn-plus {
   position: absolute !important;
   left: -2px !important;
   bottom: 5px !important;
   background: transparent !important;
   backdrop-filter: none !important;
   -webkit-backdrop-filter: none !important;
   border: none !important;
   border-radius: 50% !important;
   width: 26px !important;        
   height: 26px !important;      
   min-width: 22px !important;   
   display: flex !important;
   align-items: center !important;
   justify-content: center !important;
   margin: 0 !important;
   flex-shrink: 0 !important;
   box-shadow: none !important;
   transition: opacity 0.2s ease !important;
   cursor: pointer !important;
   z-index: 30 !important;
   transform: none !important;
}
.input-btn-plus:active {
   opacity: 0.6 !important;
   transform: none !important;
   background: transparent !important;
}
.input-btn-plus::before {
   content: "" !important;
   display: block !important;
   width: 100% !important;
   height: 100% !important;
   background-image: url("https://i.postimg.cc/3NPYgCmM/IMG_2434.png") !important;  
   background-size: contain !important;
   background-repeat: no-repeat !important;
   background-position: center !important;
}
.input-btn-plus svg {
   display: none !important;
}

/* 输入胶囊 - 浅灰色背景 #f5f5f5 */
.input-action-bar-custom {
   flex: 1 !important;
   margin-left: 90px !important;
   margin-right: 40px !important;
   transform: translateY(2px) !important;
   background: #f5f5f5 !important;
   backdrop-filter: none !important;
   -webkit-backdrop-filter: none !important;
   border: none !important;
   border-radius: 30px !important;
   padding: 0px 12px 0px 16px !important;
   min-height: 30px !important;
   display: flex !important;
   align-items: center !important;
   gap: 8px !important;
   box-shadow: none !important;
   transition: all 0.2s ease !important;
   position: relative !important;
}

.input-box-custom {
   flex: 1 !important;
   background: transparent !important;
   border: none !important;
   color: #000000 !important;
   font-size: 16px !important;
   font-weight: 400 !important;
   line-height: 1.4 !important;
   padding: 12px 0 10px 0 !important;
   margin: 0 !important;
   resize: none !important;
   outline: none !important;
   -webkit-text-fill-color: #000000 !important;
}
.input-box-custom::placeholder {
   color: rgba(0, 0, 0, 0.3) !important;
   -webkit-text-fill-color: rgba(0, 0, 0, 0.3) !important;
   opacity: 1 !important;
}

/* 右侧按钮组 */
.input-action-bar-custom>div:last-child {
   display: flex !important;
   flex-direction: row !important;
   align-items: center !important;
   gap: 6px !important;
   flex-shrink: 0 !important;
   margin-right: -6px !important;
}

/* ===== 表情按钮 - 保持原样 38px，不调整 ===== */
.input-btn-sticker {
   display: flex !important;
   align-items: center !important;
   justify-content: center !important;
   background: transparent !important;
   border: none !important;
   padding: 8px !important;
   margin: 0 !important;
   cursor: pointer !important;
   opacity: 1 !important;
   pointer-events: auto !important;
   width: 40px !important;
   height: 40px !important;
   order: 1 !important;
}
.input-btn-sticker:active {
   opacity: 0.5 !important;
}
.input-btn-sticker::before {
   content: "" !important;
   display: block !important;
   width: 100% !important;
   height: 100% !important;
   background-image: url("https://i.postimg.cc/3NPYgCmJ/IMG_2436.png") !important;  
   background-size: contain !important;
   background-repeat: no-repeat !important;
   background-position: center !important;
}
.input-btn-sticker svg {
   display: none !important;
}

/* ===== AI 按钮 - 调整为 28px ===== */
.input-btn-ai {
   position: absolute !important;
   right: -40px !important;
   bottom: 5px !important;      
   top: auto !important;
   transform: none !important;
   display: flex !important;
   align-items: center !important;
   justify-content: center !important;
   background: transparent !important;
   border: none !important;
   padding: 0 !important;
   margin: 0 !important;
   cursor: pointer !important;
   opacity: 1 !important;
   pointer-events: auto !important;
   width: 28px !important;       
   height: 28px !important;      
   z-index: 20 !important;
}
.input-btn-ai:active {
   opacity: 0.7 !important;
}
.input-btn-ai svg {
   display: none !important;
}
.input-btn-ai::before {
   content: "" !important;
   display: block !important;
   width: 28px !important;       
   height: 28px !important;      
   background-image: url("https://i.postimg.cc/Fz2Njg3N/IMG_2437.png") !important;  
   background-size: contain !important;
   background-repeat: no-repeat !important;
   background-position: center !important;
}

/* ===== 语音按钮 - 调整为 24px ===== */
.input-btn-mic {
   position: absolute !important;
   right: 185px !important;
   bottom: 4px !important;       
   top: auto !important;
   transform: none !important;
   display: flex !important;
   align-items: center !important;
   justify-content: center !important;
   background: transparent !important;
   border: none !important;
   padding: 0 !important;
   margin: 0 !important;
   cursor: pointer !important;
   opacity: 1 !important;
   pointer-events: auto !important;
   width: 24px !important;       
   height: 24px !important;      
   z-index: 20 !important;
}
.input-btn-mic:active {
   opacity: 0.7 !important;
}
.input-btn-mic svg {
   display: none !important;
}
.input-btn-mic::before {
   content: "" !important;
   display: block !important;
   width: 24px !important;       
   height: 24px !important;      
   background-image: url("https://i.postimg.cc/T1Zfrqg2/IMG_2438.png") !important;  
   background-size: contain !important;
   background-repeat: no-repeat !important;
   background-position: center !important;
}

.send-btn-custom {
   display: none !important;
}

/* 更多菜单 */
.input-area-custom .more-options-popup {
   background: #ffffff !important;
   backdrop-filter: none !important;
   -webkit-backdrop-filter: none !important;
   border-radius: 20px !important;
   border: 1px solid rgba(0, 0, 0, 0.1) !important;
   box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12) !important;
   overflow: hidden !important;
   padding: 8px 0 !important;
}
.input-area-custom .more-options-item-row {
   padding: 12px 16px !important;
   transition: background 0.15s ease !important;
   cursor: pointer !important;
}
.input-area-custom .more-options-item-row:active {
   background: rgba(0, 0, 0, 0.04) !important;
}
.input-area-custom .more-options-item-row span {
   color: #000000 !important;
   font-size: 15px !important;
   font-weight: 500 !important;
}

/* 消息列表底部空间 */
.chat-message-list-custom {
   padding-bottom: calc(80px + var(--nuo-safe-bottom)) !important;
}

/* 自定义占位提示词 */
.input-action-bar-custom::before {
   content: "发消息" !important;
   position: absolute !important;
   left: 16px !important;
   top: 50% !important;
   transform: translateY(-50%) !important;
   color: rgba(0, 0, 0, 0.25) !important;
   font-size: 14px !important;
   opacity: 1 !important;
   pointer-events: none !important;
   z-index: 10 !important;
}

.input-action-bar-custom:has(.input-box-custom:focus)::before,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::before {
   display: none !important;
}

.input-box-custom::placeholder {
   color: transparent !important;
   opacity: 0 !important;
}

.input-box-custom {
   color: #000000 !important;
   -webkit-text-fill-color: #000000 !important;
   caret-color: #000000 !important;
}

