}
.voice-msg-me .voice-transcription {
    align-self: flex-end !important;
    margin-left: auto !important;
    display: block !important;
}
.voice-play-btn {
    left: -12px !important;
    right: auto !important;
    padding: 0 !important;
    height: 24px !important;
    width: 24px !important;
    background-color: transparent !important;
    border-radius: 0;
    z-index: 12;
}
.msg-me .voice-play-btn {
    order: 2;
    left: auto !important;
    right: -12px !important;
    transform: scaleX(-1);
}
.voice-play-btn svg {
    margin: 0 !important;
    color: transparent;
    background-image: var(--voice-btn);
    background-size: contain;
    background-repeat: no-repeat;
    background-color: transparent;
}
.voice-waveform {
    opacity: 0;
    margin: 0;
    height: 12px !important;
}
.msg-them .voice-duration {
    position: absolute !important;
    left: 5px;
    margin-right: 3px;
    color: transparent !important;
}
.msg-them .voice-duration::after {
    content: '17"' !important;
    font-size: 12px !important;
    color: var(--bubble-them-color) !important;
}
.msg-me .voice-duration {
    position: absolute !important;
    right: 42px;
    margin-left: -7px;
    color: transparent !important;
}
.msg-me .voice-duration::after {
    content: '12"' !important;
    position: absolute !important;
    font-size: 12px !important;
    color: var(--bubble-me-color) !important;
}
/* 引用 */
:is(.bubble-me-custom, .bubble-them-custom):has(.msg-reply-block) {
    margin-bottom: 0 !important;
    position: relative !important;
}
.msg-reply-block { 
    display: none !important; 
}
.msg-reply-block-detached {
    display: flex !important;
    align-items: center !important;
    background: var(--reply-detached-bg) !important;
    border: var(--reply-detached-border) !important;
    border-radius: var(--reply-detached-radius) !important;
    padding: var(--reply-detached-padding) !important;
    max-width: var(--reply-detached-max-width) !important;
    margin-top: var(--reply-detached-margin-top) !important;
    width: fit-content !important;
    box-shadow: none !important;
}
.msg-reply-detached-them { 
